            TemplateHandler.Assign(ref TotalRow, "comm-nextcorner", AccCommon.DecFormat(Grand_comm_NextCorner, 0));

            #endregion comm

            #region margin

            TemplateHandler.Assign(ref TotalRow, "m-hthdp", Grand_m_hthdp);
            TemplateHandler.Assign(ref TotalRow, "m-hdp", Grand_m_hdp);
            TemplateHandler.Assign(ref TotalRow, "m-htou", Grand_m_htou);
            TemplateHandler.Assign(ref TotalRow, "m-ou", Grand_m_ou);
            TemplateHandler.Assign(ref TotalRow, "m-ht1x2", Grand_m_ht1x2);
            TemplateHandler.Assign(ref TotalRow, "m-1x2", Grand_m_1x2);
            //TemplateHandler.Assign(ref TotalRow, "m-ng", Grand_m_ng);
            TemplateHandler.Assign(ref TotalRow, "m-1stcorner", Grand_m_1stcorner);
            TemplateHandler.Assign(ref TotalRow, "m-corner", Grand_m_corner);
            TemplateHandler.Assign(ref TotalRow, "m-15mou", Grand_m_15mou);
            TemplateHandler.Assign(ref TotalRow, "m-1stYelloCard", Grand_m_1stYellowCard);
            TemplateHandler.Assign(ref TotalRow, "m-YelloCard", Grand_m_YellowCard);
            TemplateHandler.Assign(ref TotalRow, "m-1stoe", Grand_m_1stoe);
            TemplateHandler.Assign(ref TotalRow, "m-oe", Grand_m_oe);
            TemplateHandler.Assign(ref TotalRow, "m-overall", Grand_m_overall);
            TemplateHandler.Assign(ref TotalRow, "m-nextcorner", Grand_m_NextCorner);

            #endregion margin

            #endregion assing grand total

            reportRows.Append(TotalRow);
        }
        else
        {
            string norow = WebUtils.LoadTemplate("NoInformation.htm");
            if (IsSoccer == 0)
                TemplateHandler.Assign(ref norow, "{tdno}", "53");
            else
                TemplateHandler.Assign(ref norow, "{tdno}", "79");
            TemplateHandler.Assign(ref norow, "{nodata}", "<center>" + ResourceExtension.GetResourceValue(ResourceExtension.Resources.Language, "thereisnodata") + "</center>");
            reportRows.Append(norow);
        }
        TemplateHandler.Assign(ref tpl, "trader-rows", reportRows.ToString());

        ReportCache.REPORT_TRADER_DETAIL = tpl;
        return tpl;
    }
}